lse,"id":"osm-w1576347408"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1577606982"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1577639387"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1577701970"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1578845507"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1578966895"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1579736764"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1579736784"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1579783207"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1580447929"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1580903922"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1581069790"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1581782211"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1581907489"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1581907512"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1582969195"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1582969205"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1582993097"},{"access_note":"독립된 화장실 건물","is_always_open":false,"id":"osm-w1583185563"}]$b$::jsonb) as x(
    id text, access_note text, has_accessible boolean, has_diaper_table boolean, has_emergency_bell boolean,
    has_cctv boolean, is_unisex boolean, managing_org text, phone text, floor text, open_hours text,
    address text, is_always_open boolean, building_name text)
), upd as (
  update public.toilets t set
    access_note        = coalesce(t.access_note, left(s.access_note,200)),
    has_accessible     = coalesce(t.has_accessible, s.has_accessible),
    has_diaper_table   = coalesce(t.has_diaper_table, s.has_diaper_table),
    has_emergency_bell = coalesce(t.has_emergency_bell, s.has_emergency_bell),
    has_cctv           = coalesce(t.has_cctv, s.has_cctv),
    is_unisex          = coalesce(t.is_unisex, s.is_unisex),
    managing_org       = coalesce(t.managing_org, s.managing_org),
    phone              = coalesce(t.phone, s.phone),
    floor              = coalesce(t.floor, left(s.floor,20)),
    open_hours         = coalesce(t.open_hours, s.open_hours),
    address            = coalesce(t.address, s.address),
    is_always_open     = t.is_always_open or coalesce(s.is_always_open,false),
    building_name      = coalesce(t.building_name, left(s.building_name,60))
  from src s where t.id = s.id
    and ( (t.access_note is null and s.access_note is not null) or (t.has_accessible is null and s.has_accessible is not null)
       or (t.has_diaper_table is null and s.has_diaper_table is not null) or (t.has_emergency_bell is null and s.has_emergency_bell is not null)
       or (t.has_cctv is null and s.has_cctv is not null) or (t.is_unisex is null and s.is_unisex is not null)
       or (t.managing_org is null and s.managing_org is not null) or (t.phone is null and s.phone is not null)
       or (t.floor is null and s.floor is not null) or (t.open_hours is null and s.open_hours is not null)
       or (t.address is null and s.address is not null) or (not t.is_always_open and coalesce(s.is_always_open,false))
       or (t.building_name is null and s.building_name is not null) )
  returning t.id
)
select (select count(*) from src) as rows_in, (select count(*) from upd) as updated,
       (select count(*) from public.toilets where has_accessible) as accessible_total;
